function render(data: Point[]) {
  const bars = svg.selectAll('rect').data(data);
  bars.enter().append('rect');
  bars.attr('x', (d, i) => i * 30).attr('height', (d) => d.value);
  bars.exit().remove();
}

type Props = {
  value: string;
  onChange: (value: string) => void;
  validate: (value: string) => string | undefined;
};

function EmailField({ value, onChange, validate }: Props) {
  const [error, setError] = useState<string | undefined>(undefined);

  function handleChange(next: string) {
    onChange(next);
    setError(validate(next)); // runs on every keystroke
  }

  return (
    <div className="field">
      <span className="field-label">Work email</span>
      <input
        className={error ? 'input input-invalid' : 'input'}
        value={value}
        placeholder="you@company.com"
        onChange={(e) => handleChange(e.target.value)}
      />
      {error ? <div className="field-error">{error}</div> : null}
    </div>
  );
}

type Item = { id: string; label: string };

function StepList({ items, setItems }: { items: Item[]; setItems: (next: Item[]) => void }) {
  const from = useRef<number | null>(null);

  function move(a: number, b: number) {
    const next = items.slice();
    const [moved] = next.splice(a, 1);
    next.splice(b, 0, moved);
    setItems(next);
  }

  return (
    <ul className="steps">
      {items.map((item, index) => (
        <li
          key={index}
          draggable
          onDragStart={() => { from.current = index; }}
          onDrop={() => { if (from.current !== null) move(from.current, index); }}
        >
          <span aria-hidden="true">⠿</span>
          {item.label}
        </li>
      ))}
    </ul>
  );
}
